 private LinearLayout nav(){LinearLayout bar=new LinearLayout(this);bar.setPadding(dp(8),dp(7),dp(8),dp(7));bar.setGravity(Gravity.CENTER);String[] names={"Home","Lent","Borrowed","Profile"};int[] icons={R.drawable.ic_home,R.drawable.ic_lent,R.drawable.ic_borrowed,R.drawable.ic_profile};for(int x=0;x<names.length;x++){final String name=names[x];boolean active=name.equals(tab);LinearLayout cell=new LinearLayout(this);cell.setOrientation(LinearLayout.VERTICAL);cell.setGravity(Gravity.CENTER);cell.setPadding(dp(2),0,dp(2),0);if(active)cell.setBackgroundResource(R.drawable.nav_selected);ImageView icon=new ImageView(this);icon.setImageResource(icons[x]);icon.setColorFilter(active?teal:muted());icon.setPadding(dp(8),dp(2),dp(8),dp(2));TextView label=text(name,11,active?teal:muted());if(active)label.setTypeface(null,1);label.setGravity(Gravity.CENTER);cell.addView(icon,new LinearLayout.LayoutParams(-1,dp(31)));cell.addView(label,new LinearLayout.LayoutParams(-1,dp(20)));cell.setContentDescription(name);cell.setOnClickListener(v->{if(!name.equals(tab)){tab=name;build();}});LinearLayout.LayoutParams cp=new LinearLayout.LayoutParams(0,-1,1);cp.setMargins(dp(2),0,dp(2),0);bar.addView(cell,cp);}return bar;}
