 private void head(String title,String sub){LinearLayout row=new LinearLayout(this);row.setGravity(Gravity.CENTER_VERTICAL);TextView h=text(title.startsWith("Good day")?timeGreeting():title,28,ink());h.setTypeface(Typeface.create("sans-serif",Typeface.BOLD));h.setLetterSpacing(-.025f);row.addView(h,new LinearLayout.LayoutParams(0,-2,1));if(title.startsWith("Good day")){ImageView taka=new ImageView(this);taka.setImageResource(R.drawable.taka_cutout);taka.setScaleType(ImageView.ScaleType.CENTER_INSIDE);row.addView(taka,new LinearLayout.LayoutParams(dp(58),dp(58)));}content.addView(row);TextView s=text(sub,14,muted());s.setPadding(0,0,0,dp(18));content.addView(s);}private String timeGreeting(){int hour=Calendar.getInstance().get(Calendar.HOUR_OF_DAY);String greeting=hour<12?"Good morning":hour<18?"Good afternoon":"Good evening";return greeting+", "+pref.getString("name","there")+"!";}private Button btn(String s,int c){Button b=new Button(this);b.setText(s);b.setTextColor(Color.WHITE);b.setTextSize(14);b.setAllCaps(false);b.setTypeface(null,1);b.setLetterSpacing(.01f);GradientDrawable g=new GradientDrawable(GradientDrawable.Orientation.TL_BR,new int[]{lighten(c,.14f),c});g.setCornerRadius(dp(16));b.setBackground(new android.graphics.drawable.RippleDrawable(android.content.res.ColorStateList.valueOf(0x33FFFFFF),g,null));b.setStateListAnimator(null);return b;}private int lighten(int c,float f){return Color.rgb((int)(Color.red(c)+(255-Color.red(c))*f),(int)(Color.green(c)+(255-Color.green(c))*f),(int)(Color.blue(c)+(255-Color.blue(c))*f));}private int tint(int c,float a){int base=dark()?Color.rgb(28,45,61):Color.WHITE;return Color.rgb((int)(Color.red(base)*(1-a)+Color.red(c)*a),(int)(Color.green(base)*(1-a)+Color.green(c)*a),(int)(Color.blue(base)*(1-a)+Color.blue(c)*a));}
 private void home(){head("Good day, "+pref.getString("name","there")+"!","A clear view of your money today.");List<DebtDatabase.Debt> all=visible(db.activeDebts("","All"));double lent=0,borrowed=0,collected=0,paid=0;int overdue=0,today=0;for(DebtDatabase.Debt d:all){if(d.type.equals("Lent")){lent+=d.remaining();collected+=d.paid;}else{borrowed+=d.remaining();paid+=d.paid;}if(overdue(d))overdue++;if(dueToday(d))today++;}LinearLayout banner=new LinearLayout(this);banner.setOrientation(LinearLayout.VERTICAL);banner.setBackgroundResource(R.drawable.banner_background);pad(banner,20,20);TextView cap=text("TOTAL OUTSTANDING",11,0xCCFFFFFF);cap.setLetterSpacing(.12f);cap.setTypeface(null,1);banner.addView(cap);TextView total=text(money.format(lent+borrowed),34,Color.WHITE);total.setTypeface(Typeface.create("sans-serif",Typeface.BOLD));total.setLetterSpacing(-.02f);total.setShadowLayer(dp(10),0,dp(2),0x40000000);banner.addView(total);banner.addView(text(all.size()+" active record"+(all.size()==1?"":"s")+" • Offline and private",13,Color.WHITE));content.addView(banner,new LinearLayout.LayoutParams(-1,dp(146)));LinearLayout r1=new LinearLayout(this);r1.setPadding(0,dp(12),0,0);LinearLayout.LayoutParams a=new LinearLayout.LayoutParams(0,dp(88),1);a.setMargins(0,0,dp(6),0);LinearLayout.LayoutParams b1=new LinearLayout.LayoutParams(0,dp(88),1);b1.setMargins(dp(6),0,0,0);r1.addView(stat("Money lent",money.format(lent),teal),a);r1.addView(stat("You borrowed",money.format(borrowed),coral),b1);content.addView(r1);LinearLayout r2=new LinearLayout(this);r2.setPadding(0,dp(10),0,0);LinearLayout.LayoutParams c1=new LinearLayout.LayoutParams(0,dp(82),1);c1.setMargins(0,0,dp(6),0);LinearLayout.LayoutParams d1=new LinearLayout.LayoutParams(0,dp(82),1);d1.setMargins(dp(6),0,0,0);r2.addView(stat("Collected",money.format(collected),navy),c1);r2.addView(stat("Paid",money.format(paid),navy),d1);content.addView(r2);TextView alert=text((overdue>0?"⚠ "+overdue+" overdue":"✓ No overdue debts")+"   •   "+(today>0?today+" due today":"Nothing due today"),13,overdue>0?coral:teal);alert.setPadding(dp(5),dp(12),0,dp(5));content.addView(alert);section("Quick actions");LinearLayout actions=new LinearLayout(this);Button l=btn("＋ Lend money",teal),b=btn("＋ Borrow money",coral);l.setOnClickListener(v->add("Lent"));b.setOnClickListener(v->add("Borrowed"));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(0,dp(52),1);lp.setMargins(0,0,dp(6),0);LinearLayout.LayoutParams bp=new LinearLayout.LayoutParams(0,dp(52),1);bp.setMargins(dp(6),0,0,0);actions.addView(l,lp);actions.addView(b,bp);content.addView(actions);LinearLayout recentHead=new LinearLayout(this);recentHead.setGravity(Gravity.CENTER_VERTICAL);recentHead.setPadding(0,dp(14),0,0);TextView rh=text("Recent records",18,ink());rh.setTypeface(null,1);recentHead.addView(rh,new LinearLayout.LayoutParams(0,dp(52),1));TextView see=text("See all",14,teal);see.setGravity(Gravity.CENTER_VERTICAL);see.setOnClickListener(v->{tab="Lent";build();});recentHead.addView(see,new LinearLayout.LayoutParams(-2,dp(52)));content.addView(recentHead);for(int x=0;x<Math.min(all.size(),2);x++)record(content,all.get(x));if(all.isEmpty()){LinearLayout e=new LinearLayout(this);e.setGravity(Gravity.CENTER_VERTICAL);card(e);pad(e,16,16);TextView ic=text("✎",20,teal);ic.setGravity(Gravity.CENTER);ic.setBackground(shape(tint(teal,dark()?.3f:.14f),14));e.addView(ic,new LinearLayout.LayoutParams(dp(44),dp(44)));LinearLayout w=new LinearLayout(this);w.setOrientation(LinearLayout.VERTICAL);w.setPadding(dp(14),0,0,0);TextView et=text("No records yet",16,ink());et.setTypeface(null,1);w.addView(et);w.addView(text("Tap Lend or Borrow above to add your first one.",13,muted()));e.addView(w,new LinearLayout.LayoutParams(0,-2,1));content.addView(e);}}
 private TextView stat(String label,String value,int accent){TextView s=text(label+"\n"+value+"   ›",14,ink());s.setTypeface(null,1);s.setLineSpacing(dp(7),1f);s.setBackground(shape(dark()?Color.rgb(31,58,78):Color.rgb(234,248,245),18));pad(s,17,15);s.setContentDescription(label+". Open related records.");s.setOnClickListener(v->{if(label.equals("Money lent")){tab="Lent";build();}else if(label.equals("You borrowed")){tab="Borrowed";build();}else if(label.equals("Collected"))archivedRecords("Lent");else archivedRecords("Borrowed");});return s;}
 private void records(String type) {
     boolean lending = type.equals("Lent");
     List<DebtDatabase.Debt> all = visible(db.activeDebts("", type));
     double open = 0;
     int active = 0;
     for (DebtDatabase.Debt debt : all) { if (debt.remaining() > 0) { open += debt.remaining(); active++; } }
     LinearLayout summary = new LinearLayout(this);
     summary.setOrientation(LinearLayout.VERTICAL);
     GradientDrawable sg=new GradientDrawable(GradientDrawable.Orientation.TL_BR,lending?new int[]{Color.rgb(15,42,68),Color.rgb(22,80,122),Color.rgb(23,162,160)}:new int[]{Color.rgb(122,40,52),Color.rgb(200,82,70),Color.rgb(244,162,97)});sg.setCornerRadius(dp(28));summary.setBackground(sg);
     pad(summary, 18, 20);
     TextView sc=text(lending ? "OPEN LENDING" : "OPEN BORROWING", 11, 0xCCFFFFFF);sc.setLetterSpacing(.12f);sc.setTypeface(null,1);summary.addView(sc);
     TextView amount = text(money.format(open), 27, Color.WHITE); amount.setTypeface(null, 1); summary.addView(amount);
     summary.addView(text(active + " open record" + (active == 1 ? "" : "s") + " • Updated automatically", 13, Color.WHITE));
     LinearLayout.LayoutParams summaryParams = new LinearLayout.LayoutParams(-1, dp(112)); summaryParams.setMargins(0, 0, 0, dp(14)); content.addView(summary, summaryParams);
     Button add = btn(lending ? "＋ Add money you lent" : "＋ Add money you borrowed", lending ? teal : coral);
     add.setOnClickListener(v -> add(type)); content.addView(add, new LinearLayout.LayoutParams(-1, dp(52)));
     EditText search = input("Search name, provider, or category", 1);
     LinearLayout.LayoutParams searchParams = new LinearLayout.LayoutParams(-1, dp(52)); searchParams.setMargins(0, dp(14), 0, dp(10)); content.addView(search, searchParams);
     TextView filterTitle = text("", 14, ink()); filterTitle.setVisibility(View.GONE); content.addView(filterTitle);
     LinearLayout filters = new LinearLayout(this); filters.setVisibility(View.GONE); filters.setPadding(0, dp(7), 0, dp(10));
     Button allButton = btn("All", navy); Button openButton = btn("Open", teal); Button dueButton = btn("Due today", coral);
     LinearLayout.LayoutParams chip = new LinearLayout.LayoutParams(0, dp(38), 1); chip.setMargins(0, 0, dp(4), 0); filters.addView(allButton, chip);
     LinearLayout.LayoutParams chip2 = new LinearLayout.LayoutParams(0, dp(38), 1); chip2.setMargins(dp(2), 0, dp(2), 0); filters.addView(openButton, chip2);
     LinearLayout.LayoutParams chip3 = new LinearLayout.LayoutParams(0, dp(38), 1); chip3.setMargins(dp(4), 0, 0, 0); filters.addView(dueButton, chip3); content.addView(filters);
     TextView archived = text("View completed records  ›", 14, teal); archived.setTypeface(null, 1); archived.setPadding(0, dp(14), 0, dp(2)); archived.setOnClickListener(v -> archivedRecords(type)); content.addView(archived);
     LinearLayout list = new LinearLayout(this); list.setOrientation(LinearLayout.VERTICAL); content.addView(list);
     LinearLayout pager = new LinearLayout(this); pager.setGravity(Gravity.CENTER_VERTICAL); pager.setPadding(0, dp(10), 0, dp(20));
     Button previous = btn("Show less", navy); Button next = btn("See all", teal); TextView pageText = text("Recent records", 13, muted()); pageText.setGravity(Gravity.CENTER);
     pager.addView(previous, new LinearLayout.LayoutParams(0, dp(42), 1)); pager.addView(pageText, new LinearLayout.LayoutParams(0, dp(42), 1)); pager.addView(next, new LinearLayout.LayoutParams(0, dp(42), 1)); content.addView(pager);
     final String[] mode = {"All"}; final int[] page = {0}; final int pageSize = 3;
     Runnable load = () -> { List<DebtDatabase.Debt> results = new ArrayList<>(); for (DebtDatabase.Debt debt : visible(db.activeDebts(search.getText().toString(), type))) if (matchesFilter(debt, mode[0])) results.add(debt); int pages = Math.max(1, (int) Math.ceil(results.size() / (double) pageSize)); if (page[0] >= pages) page[0] = pages - 1; list.removeAllViews(); int from = page[0] * pageSize; int to = Math.min(from + pageSize, results.size()); for (int i = from; i < to; i++) record(list, results.get(i)); if (results.isEmpty()) emptyList(list, lending); pager.setVisibility(View.GONE); };
     allButton.setOnClickListener(v -> { mode[0] = "All"; page[0] = 0; load.run(); }); openButton.setOnClickListener(v -> { mode[0] = "Open"; page[0] = 0; load.run(); }); dueButton.setOnClickListener(v -> { mode[0] = "Due"; page[0] = 0; load.run(); }); previous.setOnClickListener(v -> { if (page[0] > 0) { page[0]--; load.run(); } }); next.setOnClickListener(v -> { page[0]++; load.run(); });
     search.addTextChangedListener(new TextWatcher() { public void beforeTextChanged(CharSequence s,int a,int b,int c) { } public void onTextChanged(CharSequence s,int a,int b,int c) { page[0] = 0; load.run(); } public void afterTextChanged(Editable e) { } });
     load.run();
 }
 private boolean matchesFilter(DebtDatabase.Debt debt, String mode) { return mode.equals("All") || (mode.equals("Open") && debt.remaining() > 0) || (mode.equals("Due") && dueToday(debt)); }
 private void emptyList(LinearLayout list, boolean lending) { LinearLayout empty = new LinearLayout(this); empty.setOrientation(LinearLayout.VERTICAL); empty.setGravity(Gravity.CENTER); card(empty); pad(empty, 24, 20); ImageView taka=new ImageView(this);taka.setImageResource(R.drawable.taka_cutout);taka.setScaleType(ImageView.ScaleType.CENTER_INSIDE);empty.addView(taka,new LinearLayout.LayoutParams(dp(80),dp(80))); TextView title = text(lending ? "No lending records yet" : "No borrowing records yet", 17, ink()); title.setGravity(Gravity.CENTER); title.setTypeface(null, 1); empty.addView(title); TextView caption = text(lending ? "Taka can help you keep payments on track." : "Add a provider, amount, and due date to stay prepared.", 14, muted()); caption.setGravity(Gravity.CENTER); caption.setPadding(0, dp(6), 0, dp(16)); empty.addView(caption); Button action=btn(lending?"Add money you lent":"Add money you borrowed",lending?teal:coral);action.setOnClickListener(v->add(lending?"Lent":"Borrowed"));empty.addView(action,new LinearLayout.LayoutParams(-1,dp(48))); LinearLayout.LayoutParams p = new LinearLayout.LayoutParams(-1, -2); p.setMargins(0, dp(10), 0, dp(10)); list.addView(empty, p); }
 private String debtHealth(DebtDatabase.Debt debt) {
     if (debt.remaining() == 0) return "Paid";
     if (overdue(debt)) return "Overdue";
     if (debt.amount > 0 && debt.paid / debt.amount >= .80) return "Almost paid";
     if (debt.due != null && debt.due.matches("\\d{4}-\\d{2}-\\d{2}")) {
         Calendar soon = Calendar.getInstance(); soon.add(Calendar.DAY_OF_YEAR, 3);
         String limit = new SimpleDateFormat("yyyy-MM-dd", Locale.US).format(soon.getTime());
         if (debt.due.compareTo(today()) >= 0 && debt.due.compareTo(limit) <= 0) return "Due soon";
     }
     return "On track";
 }
 private void record(LinearLayout parent,DebtDatabase.Debt d) {
     LinearLayout box = new LinearLayout(this); box.setOrientation(LinearLayout.VERTICAL); card(box); if(selectedRecordIds.contains(d.id))box.setBackground(shape(dark()?Color.rgb(35,78,84):Color.rgb(225,246,242),20)); pad(box, 17, 17); box.setOnClickListener(v -> {if(selectedRecordIds.isEmpty())debtDetails(d);else toggleRecordSelection(d.id);}); attachRecordGestures(box,d);
     LinearLayout top = new LinearLayout(this); top.setGravity(Gravity.CENTER_VERTICAL);
     TextView avatar = personAvatar(d.person, 38); avatar.setOnClickListener(v -> personProfile(d.person)); top.addView(avatar, new LinearLayout.LayoutParams(dp(38), dp(38)));
     String category = d.category == null || d.category.isEmpty() ? "Personal" : d.category;
     String label = d.tag == null || d.tag.isEmpty() ? category : d.tag;
     LinearLayout identity = new LinearLayout(this); identity.setOrientation(LinearLayout.VERTICAL); identity.setPadding(dp(10), 0, dp(6), 0);
     TextView n = text(d.person, 17, ink()); n.setTypeface(null, 1); n.setOnClickListener(v -> personProfile(d.person)); identity.addView(n);
     TextView source = text(label.toUpperCase(Locale.getDefault()), 10, Color.WHITE); source.setTypeface(null, 1); source.setGravity(Gravity.CENTER); source.setPadding(dp(8), dp(3), dp(8), dp(3)); source.setBackground(shape(providerColor(label), 16));
     LinearLayout.LayoutParams sourceParams = new LinearLayout.LayoutParams(-2, -2); sourceParams.topMargin = dp(4); identity.addView(source, sourceParams);
     top.addView(identity, new LinearLayout.LayoutParams(0, -2, 1));
     String status = debtHealth(d);
     int healthColor = status.equals("Overdue") ? coral : status.equals("Due soon") ? Color.rgb(191, 128, 54) : status.equals("Almost paid") || status.equals("Paid") ? teal : navy;
     TextView tag = text(status, 11, Color.WHITE); tag.setTypeface(null, 1); tag.setGravity(Gravity.CENTER); tag.setPadding(dp(9), dp(4), dp(9), dp(4)); tag.setBackground(shape(healthColor, 20)); top.addView(tag);
     TextView menu = text("⋮", 26, muted()); menu.setGravity(Gravity.CENTER); menu.setContentDescription("Record actions"); menu.setOnClickListener(v -> recordMenu(menu, d)); top.addView(menu, new LinearLayout.LayoutParams(dp(32), dp(32))); box.addView(top);
     if (d.customStatus != null && !d.customStatus.trim().isEmpty()) { TextView custom = text(d.customStatus, 12, teal); custom.setPadding(0, dp(7), 0, 0); box.addView(custom); }
     TextView amount = text("Remaining " + money.format(d.remaining()), 20, ink()); amount.setTypeface(null, 1); amount.setPadding(0, dp(4), 0, 0); box.addView(amount);
     int progress = d.amount <= 0 ? 0 : (int)Math.round((d.paid / d.amount) * 100); TextView progressText = text(progress + "% paid", 12, muted()); progressText.setPadding(0, dp(7), 0, dp(4)); box.addView(progressText); ProgressBar progressBar = new ProgressBar(this, null, android.R.attr.progressBarStyleHorizontal); progressBar.setMax(100); progressBar.setProgress(progress); progressBar.setProgressTintList(android.content.res.ColorStateList.valueOf(d.type.equals("Lent")?teal:coral)); progressBar.setProgressBackgroundTintList(android.content.res.ColorStateList.valueOf(dark()?Color.rgb(57,78,95):Color.rgb(221,232,232))); box.addView(progressBar, new LinearLayout.LayoutParams(-1, dp(7))); if (d.monthlyAmount > 0 && d.remaining() > 0) { TextView monthBalance = text("Pay now  " + money.format(d.monthlyBalance()) + "  ·  Monthly " + money.format(d.monthlyAmount), 13, teal); monthBalance.setPadding(0, dp(8), 0, 0); box.addView(monthBalance); }
     String amountCaption = d.monthlyAmount > 0 ? "Total payable " : "Original ";
     TextView due = text(d.due == null || d.due.isEmpty() ? "No due date set" : "Due " + d.due + "  •  " + amountCaption + money.format(d.amount), 13, muted()); due.setPadding(0, dp(4), 0, d.monthlyAmount > 0 ? dp(3) : dp(12)); box.addView(due);
     if (d.monthlyAmount > 0 && d.remaining() > 0) { TextView schedule = text("Payment schedule  ›", 13, teal); schedule.setPadding(0, 0, 0, dp(12)); schedule.setOnClickListener(v -> paymentSchedule(d)); box.addView(schedule); }
     LinearLayout row = new LinearLayout(this); Button pay = btn(d.remaining() == 0 ? "Paid in full" : "Record payment", teal); pay.setEnabled(d.remaining() > 0); pay.setAlpha(d.remaining() > 0 ? 1f : .45f); pay.setOnClickListener(v -> payment(d)); Button h = btn("View history", navy); h.setOnClickListener(v -> paymentHistory(d)); row.addView(pay, new LinearLayout.LayoutParams(0, dp(44), 3)); LinearLayout.LayoutParams hp = new LinearLayout.LayoutParams(0, dp(44), 2); hp.setMargins(dp(9), 0, 0, 0); row.addView(h, hp); box.addView(row);
     LinearLayout.LayoutParams p = new LinearLayout.LayoutParams(-1, -2); p.setMargins(0, dp(7), 0, dp(7)); parent.addView(box, p);
 }
 private String providerInitials(String provider) { String value=provider==null?"":provider.trim(); if(value.isEmpty())return "•"; String[] words=value.replace("–"," ").replace("-"," ").split("\\s+"); String result=""; for(String word:words)if(!word.isEmpty()&&Character.isLetterOrDigit(word.charAt(0))){result+=Character.toUpperCase(word.charAt(0));if(result.length()==2)break;}return result.isEmpty()?"•":result; }
 private int providerColor(String provider) { String value=provider==null?"":provider.toLowerCase(); if(value.contains("gcash"))return Color.rgb(34,119,219); if(value.contains("maya"))return Color.rgb(27,31,42); if(value.contains("home credit"))return Color.rgb(220,48,86); if(value.contains("billease"))return Color.rgb(105,78,196); if(value.contains("tala"))return Color.rgb(38,134,119); if(value.contains("urgent"))return coral; if(value.contains("family"))return teal; if(value.contains("business"))return navy; if(value.contains("personal"))return Color.rgb(105,120,130); return teal; }
 private String initials(String name) { if (name == null || name.trim().isEmpty()) return "?"; String[] words = name.trim().split("\\s+"); String first = words[0].substring(0, 1).toUpperCase(Locale.getDefault()); return words.length > 1 ? first + words[words.length - 1].substring(0, 1).toUpperCase(Locale.getDefault()) : first; }
 private int avatarColor(String name) { int[] colors = {Color.rgb(31, 122, 140), Color.rgb(56, 103, 156), Color.rgb(131, 94, 150), Color.rgb(180, 105, 74), Color.rgb(47, 128, 107), Color.rgb(160, 91, 103)}; return colors[Math.abs((name == null ? 0 : name.trim().toLowerCase(Locale.getDefault()).hashCode()) % colors.length)]; }
 private TextView personAvatar(String name, int size) { TextView avatar = text(initials(name), size >= 44 ? 16 : 13, Color.WHITE); avatar.setTypeface(null, 1); avatar.setGravity(Gravity.CENTER); avatar.setBackground(shape(avatarColor(name), 99)); return avatar; }
 private void recordMenu(View anchor, DebtDatabase.Debt debt) { PopupMenu menu = new PopupMenu(this, anchor); menu.getMenu().add("Edit record"); menu.getMenu().add("View person profile"); menu.getMenu().add("Transaction activity"); menu.getMenu().add("Delete record"); menu.setOnMenuItemClickListener(item -> { String action = item.getTitle().toString(); if (action.startsWith("Edit")) DebtEditorDialog.show(this, db, debt, this::render); else if (action.startsWith("View person")) personProfile(debt.person); else if (action.startsWith("Transaction")) activityHistory(); else new AlertDialog.Builder(this).setTitle("Delete this record?").setMessage("It will be removed with its payment history. You will have 5 seconds to undo.").setNegativeButton("Keep", null).setPositiveButton("Delete", (d, w) -> scheduleDelete(debt)).show(); return true; }); menu.show(); }
 private void activityHistory(){content.removeAllViews();TextView back=text("‹ Back to records",15,teal);back.setPadding(0,0,0,dp(18));back.setOnClickListener(v->render());content.addView(back);TextView title=text("Transaction activity",25,ink());title.setTypeface(null,1);content.addView(title);TextView sub=text("Payments, edits, exports, and deleted records",14,muted());sub.setPadding(0,dp(4),0,dp(16));content.addView(sub);SimpleDateFormat format=new SimpleDateFormat("MMM d, yyyy · h:mm a",Locale.getDefault());for(DebtDatabase.Activity event:db.activity()){LinearLayout row=new LinearLayout(this);row.setOrientation(LinearLayout.VERTICAL);card(row);pad(row,14,16);TextView eventTitle=text(event.title,16,ink());eventTitle.setTypeface(null,1);TextView detail=text(event.detail+"\n"+format.format(new Date(event.created)),13,muted());detail.setPadding(0,dp(4),0,0);row.addView(eventTitle);row.addView(detail);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(0,dp(5),0,dp(5));content.addView(row,p);}if(db.activity().isEmpty())content.addView(text("No activity yet.",15,muted()));}
 private List<DebtDatabase.Debt> visible(List<DebtDatabase.Debt> debts) {
     List<DebtDatabase.Debt> shown = new ArrayList<>();
     for (DebtDatabase.Debt debt : debts) if (!pendingDeleteIds.contains(debt.id)) shown.add(debt);
     return shown;
 }
 private void selectionToolbar(){LinearLayout bar=new LinearLayout(this);bar.setGravity(Gravity.CENTER_VERTICAL);bar.setBackground(shape(dark()?Color.rgb(37,72,82):Color.rgb(228,246,243),18));bar.setPadding(dp(14),dp(8),dp(8),dp(8));TextView count=text(selectedRecordIds.size()+" selected",14,ink());count.setTypeface(null,1);bar.addView(count,new LinearLayout.LayoutParams(0,dp(40),1));Button export=btn("Export",navy);export.setTextSize(12);export.setOnClickListener(v->exportSelectedRecords());bar.addView(export,new LinearLayout.LayoutParams(dp(82),dp(40)));Button archive=btn("Archive",teal);archive.setTextSize(12);archive.setOnClickListener(v->archiveSelectedRecords());LinearLayout.LayoutParams archiveParams=new LinearLayout.LayoutParams(dp(84),dp(40));archiveParams.setMargins(dp(6),0,0,0);bar.addView(archive,archiveParams);TextView clear=text("×",25,muted());clear.setGravity(Gravity.CENTER);clear.setContentDescription("Clear selection");clear.setOnClickListener(v->{selectedRecordIds.clear();render();});bar.addView(clear,new LinearLayout.LayoutParams(dp(34),dp(40)));LinearLayout.LayoutParams params=new LinearLayout.LayoutParams(-1,dp(56));params.setMargins(0,0,0,dp(10));content.addView(bar,params);}
 private void exportSelectedRecords(){pendingCsvExportIds=new HashSet<>(selectedRecordIds);Intent intent=new Intent(Intent.ACTION_CREATE_DOCUMENT);intent.setType("text/csv");intent.addCategory(Intent.CATEGORY_OPENABLE);intent.putExtra(Intent.EXTRA_TITLE,"TrackUtang_Selected_Records.csv");startActivityForResult(intent,51);}
 private void archiveSelectedRecords(){new AlertDialog.Builder(this).setTitle("Archive selected records?").setMessage("They will move to Archived records and can be restored later.").setNegativeButton("Cancel",null).setPositiveButton("Archive",(dialog,which)->{for(Long id:new HashSet<>(selectedRecordIds))db.archiveDebt(id);selectedRecordIds.clear();render();}).show();}
 private void toggleRecordSelection(long id){if(selectedRecordIds.contains(id))selectedRecordIds.remove(id);else selectedRecordIds.add(id);render();}
 private void attachRecordGestures(View card,DebtDatabase.Debt debt){GestureDetector gestures=new GestureDetector(this,new GestureDetector.SimpleOnGestureListener(){@Override public boolean onDown(MotionEvent event){return true;}@Override public boolean onSingleTapUp(MotionEvent event){if(selectedRecordIds.isEmpty())debtDetails(debt);else toggleRecordSelection(debt.id);return true;}@Override public void onLongPress(MotionEvent event){toggleRecordSelection(debt.id);}@Override public boolean onFling(MotionEvent start,MotionEvent end,float velocityX,float velocityY){if(start==null||end==null)return false;float dx=end.getX()-start.getX();float dy=end.getY()-start.getY();if(Math.abs(dx)<dp(88)||Math.abs(dx)<Math.abs(dy))return false;if(dx>0){if(debt.remaining()>0)payment(debt);else Toast.makeText(MainActivity.this,"This record is already paid",Toast.LENGTH_SHORT).show();}else swipeRecordActions(debt);return true;}});card.setOnTouchListener((view,event)->{gestures.onTouchEvent(event);return true;});}
 private void swipeRecordActions(DebtDatabase.Debt debt){String[] choices={"Edit record","Delete record"};new AlertDialog.Builder(this).setTitle(debt.person).setItems(choices,(dialog,which)->{if(which==0)DebtEditorDialog.show(this,db,debt,this::render);else new AlertDialog.Builder(this).setTitle("Delete this record?").setMessage("It will be removed with its payment history.").setNegativeButton("Keep",null).setPositiveButton("Delete",(x,w)->scheduleDelete(debt)).show();}).show();}
 private void archivedRecords(String type) {
     content.removeAllViews();
     TextView back = text("‹ Back to " + type.toLowerCase(), 15, teal);
     back.setPadding(0, 0, 0, dp(18)); back.setOnClickListener(v -> render()); content.addView(back);
     TextView title = text("Archived " + type.toLowerCase(), 25, ink()); title.setTypeface(null, 1); content.addView(title);
     TextView subtitle = text("Completed and manually archived records stay here for reference.", 14, muted()); subtitle.setPadding(0, dp(4), 0, dp(16)); content.addView(subtitle);
     List<DebtDatabase.Debt> completed = visible(db.archivedDebts(type));
     if (completed.isEmpty()) { emptyList(content, type.equals("Lent")); return; }
     for (DebtDatabase.Debt debt : completed) archivedRecord(debt);
 }
 private void archivedRecord(DebtDatabase.Debt debt) {
     LinearLayout card = new LinearLayout(this); card.setOrientation(LinearLayout.VERTICAL); card(card); pad(card, 16, 16);
     LinearLayout top = new LinearLayout(this); top.setGravity(Gravity.CENTER_VERTICAL);
     top.addView(personAvatar(debt.person, 42), new LinearLayout.LayoutParams(dp(42), dp(42)));
     LinearLayout words = new LinearLayout(this); words.setOrientation(LinearLayout.VERTICAL); words.setPadding(dp(12), 0, 0, 0);
     TextView name = text(debt.person, 17, ink()); name.setTypeface(null, 1); words.addView(name);
     TextView settled = text(debt.remaining() == 0 ? "Paid in full · " + money.format(debt.amount) : "Remaining " + money.format(debt.remaining()), 13, muted()); settled.setPadding(0, dp(3), 0, 0); words.addView(settled);
     top.addView(words, new LinearLayout.LayoutParams(0, -2, 1));
     TextView paid = text(debt.remaining() == 0 ? "PAID" : "ARCHIVED", 11, Color.WHITE); paid.setTypeface(null, 1); paid.setGravity(Gravity.CENTER); paid.setPadding(dp(9), dp(5), dp(9), dp(5)); paid.setBackground(shape(debt.remaining() == 0 ? teal : navy, 18)); top.addView(paid);
     card.addView(top);
     TextView detail = text("Payment history and receipts remain available.", 13, muted()); detail.setPadding(0, dp(14), 0, dp(10)); card.addView(detail);
     LinearLayout actions = new LinearLayout(this); actions.setGravity(Gravity.CENTER_VERTICAL);
     Button history = btn("View history", navy); history.setOnClickListener(v -> paymentHistory(debt)); actions.addView(history, new LinearLayout.LayoutParams(0, dp(46), 1));
     Button restore = btn("Restore", teal); restore.setOnClickListener(v -> { db.restoreDebt(debt.id); Toast.makeText(this, debt.person + " restored to active records", Toast.LENGTH_SHORT).show(); archivedRecords(debt.type); }); LinearLayout.LayoutParams restoreParams = new LinearLayout.LayoutParams(0, dp(46), 1); restoreParams.setMargins(dp(8), 0, 0, 0); actions.addView(restore, restoreParams);
     card.addView(actions);
     LinearLayout.LayoutParams cardParams = new LinearLayout.LayoutParams(-1, -2); cardParams.setMargins(0, dp(5), 0, dp(5)); content.addView(card, cardParams);
 }
 private void personProfile(String person) {
     content.removeAllViews();
     TextView back = text("‹ Back to records", 15, teal); back.setPadding(0, 0, 0, dp(18)); back.setOnClickListener(v -> render()); content.addView(back);
     TextView title = text(person, 26, ink()); title.setTypeface(null, 1); content.addView(title);
     List<DebtDatabase.Debt> records = new ArrayList<>();
     for (DebtDatabase.Debt debt : db.debts("", "All")) if (person.equalsIgnoreCase(debt.person)) records.add(debt);
     double open = 0; double settled = 0;
     for (DebtDatabase.Debt debt : records) { open += debt.remaining(); settled += debt.paid; }
     TextView summary = text("Open balance  " + money.format(open) + "\nTotal payments  " + money.format(settled) + "\n" + records.size() + " record" + (records.size() == 1 ? "" : "s"), 16, ink());
     summary.setLineSpacing(dp(6), 1f); summary.setBackground(shape(dark() ? Color.rgb(31,58,78) : Color.rgb(234,248,245), 20)); pad(summary, 18, 18); content.addView(summary);
     TextView label = text("RECORDS", 13, teal); label.setTypeface(null, 1); label.setPadding(0, dp(20), 0, dp(6)); content.addView(label);
     for (DebtDatabase.Debt debt : records) record(content, debt);
 }
 private void scheduleDelete(DebtDatabase.Debt debt) {
     pendingDeleteIds.add(debt.id); render();
     Runnable commit = () -> { if (pendingDeleteIds.remove(debt.id)) db.deleteDebt(debt.id); };
     uiHandler.postDelayed(commit, 5000);
     showUndoBar(debt, commit);
 }
 private void showUndoBar(DebtDatabase.Debt debt, Runnable commit) {
     LinearLayout bar = new LinearLayout(this); bar.setGravity(Gravity.CENTER_VERTICAL); bar.setPadding(dp(16), dp(10), dp(10), dp(10)); bar.setBackground(shape(navy, 18));
     TextView message = text("Record deleted", 14, Color.WHITE); bar.addView(message, new LinearLayout.LayoutParams(0, dp(42), 1));
     Button undo = btn("Undo", teal); undo.setOnClickListener(v -> { pendingDeleteIds.remove(debt.id); uiHandler.removeCallbacks(commit); render(); }); bar.addView(undo, new LinearLayout.LayoutParams(dp(82), dp(42)));
     PopupWindow popup = new PopupWindow(bar, -1, -2, false); popup.setBackgroundDrawable(shape(navy, 18)); popup.setElevation(dp(8)); popup.setOutsideTouchable(false); popup.showAtLocation(getWindow().getDecorView(), Gravity.BOTTOM | Gravity.CENTER_HORIZONTAL, dp(18), dp(92));
     uiHandler.postDelayed(popup::dismiss, 5000);
 }
