 private void debtDetails(DebtDatabase.Debt d){content.removeAllViews();TextView back=text("‹ Back to records",15,teal);back.setPadding(0,0,0,dp(18));back.setOnClickListener(v->render());content.addView(back);TextView title=text(d.person,26,ink());title.setTypeface(null,1);content.addView(title);TextView category=text(d.category==null?"Personal":d.category,14,teal);category.setPadding(0,dp(4),0,dp(16));content.addView(category);LinearLayout balanceCard=new LinearLayout(this);balanceCard.setOrientation(LinearLayout.VERTICAL);balanceCard.setBackground(shape(dark()?Color.rgb(31,58,78):Color.rgb(234,248,245),20));pad(balanceCard,18,18);TextView caption=text("REMAINING BALANCE",12,dark()?Color.WHITE:navy);TextView amount=text(money.format(d.remaining()),27,ink());amount.setTypeface(null,1);balanceCard.addView(caption);balanceCard.addView(amount);content.addView(balanceCard,new LinearLayout.LayoutParams(-1,dp(100)));TextView details=text("Original amount  "+money.format(d.amount)+"\nPaid so far  "+money.format(d.paid)+"\nDue date  "+(d.due==null||d.due.isEmpty()?"Not set":d.due)+(d.monthlyAmount>0?"\nMonthly payment  "+money.format(d.monthlyAmount)+"\nPayments remaining  "+d.installmentsRemaining:"")+(d.note==null||d.note.isEmpty()?"":"\nNotes  "+d.note),15,ink());details.setLineSpacing(dp(5),1f);details.setPadding(0,dp(18),0,dp(12));content.addView(details);Button pay=btn(d.remaining()>0?"Record payment":"Paid in full",teal);pay.setEnabled(d.remaining()>0);pay.setOnClickListener(v->payment(d));content.addView(pay,new LinearLayout.LayoutParams(-1,dp(50)));TextView link=text("View full payment history →",15,teal);link.setPadding(0,dp(18),0,dp(10));link.setOnClickListener(v->history(d));content.addView(link);}
