 private void profile(){String name=pref.getString("name","Set your name");head("Profile","Your personal, private money space.");LinearLayout hero=new LinearLayout(this);hero.setGravity(Gravity.CENTER_VERTICAL);card(hero);pad(hero,18,18);TextView avatar=text(name.substring(0,1).toUpperCase(),22,Color.WHITE);avatar.setGravity(Gravity.CENTER);avatar.setTypeface(null,1);avatar.setBackgroundResource(R.drawable.avatar_background);hero.addView(avatar,new LinearLayout.LayoutParams(dp(54),dp(54)));LinearLayout words=new LinearLayout(this);words.setOrientation(LinearLayout.VERTICAL);words.setPadding(dp(14),0,0,0);TextView user=text(name,20,Color.WHITE);user.setTypeface(null,1);words.addView(user);words.addView(text("🔒 Local profile · No account needed",13,0xDDFFFFFF));hero.addView(words,new LinearLayout.LayoutParams(0,-2,1));hero.setBackgroundResource(R.drawable.banner_background);avatar.setBackground(shape(0x33FFFFFF,99));TextView edit=text("Edit",14,Color.WHITE);edit.setTypeface(null,1);edit.setPadding(dp(14),dp(7),dp(14),dp(7));edit.setBackground(shape(0x33FFFFFF,99));edit.setOnClickListener(v->editName());hero.addView(edit);content.addView(hero);section("Manage your app");item("Settings","Theme, reminders, security, and data controls.",v->settingsHub());section("Your data");item("Export records","Save a CSV spreadsheet on your device.",v->exportCsv());item("Import records","Import a TrackUtang CSV backup.",v->importCsv());section("Privacy & legal");item("Privacy policy","Read how your financial data is protected.",v->document("Privacy Policy",privacy()));item("Data policy","Understand storage, exports, and deletion.",v->document("Data Policy",dataPolicy()));item("Disclaimer","Personal record-keeping only.",v->document("Disclaimer","TrackUtang is a personal organizer, not legal proof of debt and not financial or legal advice."));item("About TrackUtang","Version 1.0 · Offline personal debt tracker",null);}
