 private String privacy(){return "Privacy Policy\nEffective: July 10, 2026\n\nTrackUtang is an offline personal record-keeping app. It does not require an account, registration, cloud sync, analytics, or advertising SDKs. The local display name, debt records, contact numbers, categories, due dates, payment history, and activity history remain in the app database on your device. Arceb Studio does not receive, view, sell, or share these records.\n\nNotifications: TrackUtang requests notification permission only to send due-date reminders that you create. Notification content is generated locally and is not sent to a server.\n\nFiles: CSV backups and receipt images are created only when you choose Export or Save receipt. Import files are read only after you choose them. These files may contain financial information; store and share them carefully.\n\nRetention and deletion: Data stays on your device until you edit, delete, uninstall the app, or choose Delete all local data.\n\nContact: For privacy questions, contact arcebstudio@gmail.com.";}private String dataPolicy(){return "Data Policy\n\nTrackUtang uses data only to provide its expected local features: tracking debts, calculating balances, scheduling local reminders, showing payment and activity history, and creating user-requested CSV or receipt files.\n\nThe app does not transmit financial records, contacts, or the local display name to Arceb Studio or third parties. The feedback button opens your email app; any email you send is governed by your email provider.\n\nGoogle Play Data Safety: For this version, declare accurately based on the final released build. If no analytics, ads, or cloud SDK is added, the app does not collect or share user data with the developer. If you later add an SDK, ads, cloud backup, or analytics, update this policy and the Google Play Data safety form before release.";}
 private void exportCsv() {
     Intent intent = new Intent(Intent.ACTION_CREATE_DOCUMENT);
     intent.setType("text/csv");
     intent.addCategory(Intent.CATEGORY_OPENABLE);
     intent.putExtra(Intent.EXTRA_TITLE, "TrackUtang_Backup_" + new SimpleDateFormat("yyyy-MM-dd", Locale.US).format(new Date()) + ".csv");
     startActivityForResult(intent, 51);
 }
 private void importCsv() { Intent intent = new Intent(Intent.ACTION_OPEN_DOCUMENT); intent.setType("text/csv"); intent.addCategory(Intent.CATEGORY_OPENABLE); intent.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION); startActivityForResult(intent, 52); }
 private void paymentSchedule(DebtDatabase.Debt debt) {
     content.removeAllViews();
     TextView back = text("‹ Back to records", 15, teal);
     back.setPadding(0, 0, 0, dp(18));
     back.setOnClickListener(v -> render());
     content.addView(back);
     TextView title = text("Payment schedule", 25, ink());
     title.setTypeface(null, 1);
     content.addView(title);
     TextView summary = text(money.format(debt.monthlyAmount) + " each month · " + debt.installmentsRemaining + " payment" + (debt.installmentsRemaining == 1 ? "" : "s") + " remaining", 14, muted());
     summary.setPadding(0, dp(4), 0, dp(16));
     content.addView(summary);
     Calendar calendar = Calendar.getInstance();
     try { calendar.setTime(new SimpleDateFormat("yyyy-MM-dd", Locale.US).parse(debt.due)); } catch (Exception ignored) { }
     SimpleDateFormat dates = new SimpleDateFormat("MMM d, yyyy", Locale.getDefault());
     for (int i = 0; i < debt.installmentsRemaining; i++) {
         LinearLayout row = new LinearLayout(this); row.setGravity(Gravity.CENTER_VERTICAL); card(row); pad(row, 14, 16);
         LinearLayout labels = new LinearLayout(this); labels.setOrientation(LinearLayout.VERTICAL);
         TextView number = text("Payment " + (i + 1), 16, ink());
         TextView date = text(dates.format(calendar.getTime()), 13, muted());
         date.setPadding(0, dp(3), 0, 0); labels.addView(number); labels.addView(date);
         row.addView(labels, new LinearLayout.LayoutParams(0, -2, 1));
         double scheduledAmount = i == 0 ? debt.monthlyBalance() : Math.min(debt.monthlyAmount, debt.remaining());
         TextView amount = text(money.format(scheduledAmount), 15, teal);
         amount.setTypeface(null, 1); row.addView(amount);
         LinearLayout.LayoutParams p = new LinearLayout.LayoutParams(-1, -2);
         p.setMargins(0, dp(5), 0, dp(5)); content.addView(row, p); calendar.add(Calendar.MONTH, 1);
     }
 }
