     ImageView taka = null;
     if (debt.remaining() == 0) { taka = new ImageView(this); taka.setImageResource(R.drawable.taka_cutout); taka.setScaleType(ImageView.ScaleType.CENTER_INSIDE); LinearLayout.LayoutParams mascotParams = new LinearLayout.LayoutParams(-1, dp(94)); mascotParams.setMargins(0, 0, 0, dp(4)); body.addView(taka, mascotParams); }
     TextView total = text(debt.remaining() == 0 ? "Paid in full" : "Payment recorded", 21, ink()); total.setTypeface(null, 1); body.addView(total);
