     TextView receipt = text("Save and share receipt image  ›", 15, teal); receipt.setPadding(dp(16), dp(14), dp(16), dp(14)); receipt.setBackground(shape(dark() ? Color.rgb(31,58,78) : Color.rgb(234,248,245), 16)); body.addView(receipt);
     final Dialog[] modal = new Dialog[1];
