 private void homeMonthlySummary() {
    Calendar month = Calendar.getInstance();
    month.set(Calendar.DAY_OF_MONTH, 1); month.set(Calendar.HOUR_OF_DAY, 0); month.set(Calendar.MINUTE, 0); month.set(Calendar.SECOND, 0);
    long start = month.getTimeInMillis(); double received = 0; double paid = 0; double due = 0;
    String currentMonth = new SimpleDateFormat("yyyy-MM", Locale.US).format(new Date());
    for (DebtDatabase.Debt debt : visible(db.activeDebts("", "All"))) {
        if (debt.due != null && debt.due.startsWith(currentMonth)) due += debt.remaining();
        for (DebtDatabase.Payment payment : db.payments(debt.id)) if (payment.paidAt >= start) { if (debt.type.equals("Lent")) received += payment.amount; else paid += payment.amount; }
    }
    TextView label = text("THIS MONTH", 13, teal); label.setTypeface(null, 1); label.setPadding(0, dp(18), 0, dp(8)); content.addView(label);
    LinearLayout card = new LinearLayout(this); card.setOrientation(LinearLayout.VERTICAL); card.setBackground(shape(dark() ? Color.rgb(31,58,78) : Color.rgb(234,248,245), 20)); pad(card, 16, 18);
    LinearLayout header = new LinearLayout(this); header.setGravity(Gravity.CENTER_VERTICAL);
    TextView heading = text("Monthly snapshot", 17, ink()); heading.setTypeface(null, 1); header.addView(heading, new LinearLayout.LayoutParams(0, -2, 1));
    TextView period = text(new SimpleDateFormat("MMMM", Locale.getDefault()).format(new Date()), 13, muted()); header.addView(period); card.addView(header);
    TextView helper = text("A quick view of cash movement and upcoming balances.", 13, muted()); helper.setPadding(0, dp(4), 0, dp(12)); card.addView(helper);
    LinearLayout tiles = new LinearLayout(this); tiles.setGravity(Gravity.CENTER_VERTICAL);
    String[] titles = {"Received", "Paid", "Due"}; double[] amounts = {received, paid, due}; int[] accents = {teal, navy, coral};
    for (int i = 0; i < titles.length; i++) { final String destination=titles[i].equals("Received")?"Lent":titles[i].equals("Paid")?"Borrowed":null; LinearLayout tile = new LinearLayout(this); tile.setOrientation(LinearLayout.VERTICAL); tile.setBackground(shape(dark() ? Color.rgb(40,65,82) : Color.WHITE, 15)); tile.setPadding(dp(10), dp(10), dp(10), dp(10)); TextView title = text(titles[i], 12, muted()); TextView value = text(compactMoney(amounts[i]), 13, accents[i]); value.setTypeface(null, 1); value.setSingleLine(true); value.setContentDescription(titles[i] + " " + money.format(amounts[i])); value.setPadding(0, dp(4), 0, 0); tile.addView(title); tile.addView(value); tile.setOnClickListener(v->{if(destination!=null){tab=destination;build();}else CalendarOverviewDialog.show(this,db);}); LinearLayout.LayoutParams size = new LinearLayout.LayoutParams(0, dp(68), 1); if (i == 0) size.setMargins(0, 0, dp(4), 0); else if (i == 2) size.setMargins(dp(4), 0, 0, 0); else size.setMargins(dp(2), 0, dp(2), 0); tiles.addView(tile, size); }
    card.addView(tiles);
    LinearLayout.LayoutParams params = new LinearLayout.LayoutParams(-1, -2); params.setMargins(0, 0, 0, dp(4)); content.addView(card, params);
 }
 private String compactMoney(double amount) { double absolute = Math.abs(amount); if (absolute >= 1000000) return String.format(Locale.getDefault(), "₱%.1fM", amount / 1000000d); if (absolute >= 1000) return String.format(Locale.getDefault(), "₱%.1fK", amount / 1000d); return money.format(amount); }
