 private void homeFinanceInsights(){List<DebtDatabase.Debt> all=db.debts("","All");List<DebtDatabase.Debt> active=visible(db.activeDebts("","All"));TextView label=text("MONEY INSIGHTS",13,teal);label.setTypeface(null,1);label.setPadding(0,dp(18),0,dp(8));content.addView(label);
     LinearLayout trend=new LinearLayout(this);trend.setOrientation(LinearLayout.VERTICAL);trend.setBackground(shape(dark()?Color.rgb(31,58,78):Color.WHITE,20));pad(trend,15,16);TextView trendTitle=text("Cash-flow trend",16,ink());trendTitle.setTypeface(null,1);trend.addView(trendTitle);TextView trendDetail=text("New lending and borrowing · last 6 months",13,muted());trendDetail.setPadding(0,dp(3),0,dp(12));trend.addView(trendDetail);double[] lent=new double[6],borrowed=new double[6];Calendar cursor=Calendar.getInstance();cursor.set(Calendar.DAY_OF_MONTH,1);cursor.set(Calendar.HOUR_OF_DAY,0);cursor.set(Calendar.MINUTE,0);cursor.set(Calendar.SECOND,0);for(DebtDatabase.Debt debt:all){for(int i=0;i<6;i++){Calendar start=(Calendar)cursor.clone();start.add(Calendar.MONTH,i-5);Calendar end=(Calendar)start.clone();end.add(Calendar.MONTH,1);if(debt.created>=start.getTimeInMillis()&&debt.created<end.getTimeInMillis()){if(debt.type.equals("Lent"))lent[i]+=debt.principal;else borrowed[i]+=debt.principal;}}}double maximum=1;for(int i=0;i<6;i++)maximum=Math.max(maximum,Math.max(lent[i],borrowed[i]));LinearLayout chart=new LinearLayout(this);chart.setGravity(Gravity.BOTTOM);for(int i=0;i<6;i++){LinearLayout column=new LinearLayout(this);column.setOrientation(LinearLayout.VERTICAL);column.setGravity(Gravity.CENTER_HORIZONTAL);FrameLayout bars=new FrameLayout(this);LinearLayout pair=new LinearLayout(this);pair.setGravity(Gravity.BOTTOM|Gravity.CENTER_HORIZONTAL);View lentBar=new View(this);lentBar.setBackground(shape(teal,6));View borrowedBar=new View(this);borrowedBar.setBackground(shape(coral,6));int lentHeight=Math.max(dp(4),(int)(dp(50)*lent[i]/maximum));int borrowedHeight=Math.max(dp(4),(int)(dp(50)*borrowed[i]/maximum));LinearLayout.LayoutParams lentParams=new LinearLayout.LayoutParams(dp(7),lentHeight);lentParams.setMargins(0,0,dp(3),0);pair.addView(lentBar,lentParams);pair.addView(borrowedBar,new LinearLayout.LayoutParams(dp(7),borrowedHeight));bars.addView(pair,new FrameLayout.LayoutParams(-1,dp(54),Gravity.BOTTOM));column.addView(bars,new LinearLayout.LayoutParams(-1,dp(54)));Calendar month=(Calendar)cursor.clone();month.add(Calendar.MONTH,i-5);TextView monthName=text(new SimpleDateFormat("MMM",Locale.getDefault()).format(month.getTime()),11,muted());monthName.setGravity(Gravity.CENTER);column.addView(monthName,new LinearLayout.LayoutParams(-1,dp(22)));chart.addView(column,new LinearLayout.LayoutParams(0,dp(76),1));}trend.addView(chart);TextView key=text("● Lent     ● Borrowed",12,muted());key.setTextColor(teal);key.setPadding(0,dp(4),0,0);trend.addView(key);LinearLayout.LayoutParams trendParams=new LinearLayout.LayoutParams(-1,-2);trendParams.setMargins(0,0,0,dp(8));content.addView(trend,trendParams);
     double principal=0,interest=0,borrowedRemaining=0,scheduled=0;for(DebtDatabase.Debt debt:active)if(debt.type.equals("Borrowed")){borrowedRemaining+=debt.remaining();if(debt.monthlyAmount>0){principal+=debt.principal;interest+=debt.interestTotal();scheduled+=Math.min(debt.monthlyAmount,debt.remaining());}}LinearLayout insightRow=new LinearLayout(this);insightRow.setGravity(Gravity.CENTER_VERTICAL);LinearLayout interestTile=financeTile("Interest cost",interest>0?compactMoney(interest):"None",interest>0?"Across active plans":"No active interest plans",teal);interestTile.setOnClickListener(v->{tab="Borrowed";build();});insightRow.addView(interestTile,new LinearLayout.LayoutParams(0,dp(116),1));LinearLayout payoffTile=financeTile("Payoff outlook",scheduled>0?Math.max(1,(int)Math.ceil(borrowedRemaining/scheduled))+" mo":"—",scheduled>0?"At scheduled payments":"Add a monthly plan",navy);payoffTile.setOnClickListener(v->{tab="Borrowed";build();});LinearLayout.LayoutParams payoffParams=new LinearLayout.LayoutParams(0,dp(116),1);payoffParams.setMargins(dp(8),0,0,0);insightRow.addView(payoffTile,payoffParams);content.addView(insightRow);
     LinearLayout aging=new LinearLayout(this);aging.setOrientation(LinearLayout.VERTICAL);aging.setBackground(shape(dark()?Color.rgb(31,58,78):Color.WHITE,20));pad(aging,15,16);TextView agingTitle=text("Debt aging",16,ink());agingTitle.setTypeface(null,1);aging.addView(agingTitle);TextView agingDetail=text("Open balances by how long the record has been active",13,muted());agingDetail.setPadding(0,dp(3),0,dp(10));aging.addView(agingDetail);double fresh=0,mid=0,old=0;long now=System.currentTimeMillis();for(DebtDatabase.Debt debt:active){long days=(now-debt.created)/(24L*60L*60L*1000L);if(days<30)fresh+=debt.remaining();else if(days<90)mid+=debt.remaining();else old+=debt.remaining();}LinearLayout ageTiles=new LinearLayout(this);ageTiles.addView(ageTile("Under 30d",fresh),new LinearLayout.LayoutParams(0,dp(62),1));LinearLayout.LayoutParams middleParams=new LinearLayout.LayoutParams(0,dp(62),1);middleParams.setMargins(dp(5),0,dp(5),0);ageTiles.addView(ageTile("1–3 mo",mid),middleParams);ageTiles.addView(ageTile("Over 3 mo",old),new LinearLayout.LayoutParams(0,dp(62),1));aging.addView(ageTiles);LinearLayout.LayoutParams agingParams=new LinearLayout.LayoutParams(-1,-2);agingParams.setMargins(0,dp(8),0,dp(8));content.addView(aging,agingParams);
     Calendar nextMonth=Calendar.getInstance();nextMonth.add(Calendar.MONTH,1);String nextKey=new SimpleDateFormat("yyyy-MM",Locale.US).format(nextMonth.getTime());double expectedCollect=0,expectedPay=0;for(DebtDatabase.Debt debt:active){double expected=debt.monthlyAmount>0?Math.min(debt.monthlyAmount,debt.remaining()):(debt.due!=null&&debt.due.startsWith(nextKey)?debt.remaining():0);if(debt.type.equals("Lent"))expectedCollect+=expected;else expectedPay+=expected;}LinearLayout forecast=new LinearLayout(this);forecast.setOrientation(LinearLayout.VERTICAL);forecast.setBackground(shape(dark()?Color.rgb(36,64,75):Color.rgb(232,246,244),20));pad(forecast,15,16);TextView forecastTitle=text("Next month forecast",16,ink());forecastTitle.setTypeface(null,1);forecast.addView(forecastTitle);TextView forecastDetail=text("Expected collections  "+compactMoney(expectedCollect)+"     Expected payments  "+compactMoney(expectedPay),13,muted());forecastDetail.setPadding(0,dp(5),0,0);forecast.addView(forecastDetail);LinearLayout.LayoutParams forecastParams=new LinearLayout.LayoutParams(-1,-2);forecastParams.setMargins(0,0,0,dp(4));content.addView(forecast,forecastParams);}
