 private void homeWellnessPrompt() {
     Calendar now = Calendar.getInstance();
     Calendar currentStart = (Calendar) now.clone(); currentStart.set(Calendar.DAY_OF_MONTH, 1); currentStart.set(Calendar.HOUR_OF_DAY, 0); currentStart.set(Calendar.MINUTE, 0); currentStart.set(Calendar.SECOND, 0); currentStart.set(Calendar.MILLISECOND, 0);
     Calendar previousStart = (Calendar) currentStart.clone(); previousStart.add(Calendar.MONTH, -1);
     double currentBorrowed = 0; double previousBorrowed = 0;
     for (DebtDatabase.Debt debt : db.debts("", "Borrowed")) {
         if (debt.created >= currentStart.getTimeInMillis()) currentBorrowed += debt.principal;
         else if (debt.created >= previousStart.getTimeInMillis()) previousBorrowed += debt.principal;
     }
     boolean rising = currentBorrowed >= 1000 && (previousBorrowed == 0 || currentBorrowed >= previousBorrowed * 1.25);
     if (!rising) return;
     LinearLayout card = new LinearLayout(this); card.setOrientation(LinearLayout.VERTICAL); card.setBackground(shape(dark() ? Color.rgb(70,58,43) : Color.rgb(255,247,231), 20)); pad(card, 14, 16);
     TextView title = text("A gentle money check-in", 16, ink()); title.setTypeface(null, 1); card.addView(title);
     TextView detail = text("New borrowing this month is " + money.format(currentBorrowed) + ". Review upcoming payments before taking on more.", 13, muted()); detail.setLineSpacing(dp(3), 1f); detail.setPadding(0, dp(4), 0, 0); card.addView(detail);
     LinearLayout.LayoutParams params = new LinearLayout.LayoutParams(-1, -2); params.setMargins(0, dp(8), 0, dp(4)); content.addView(card, params);
 }
 @Override protected void onActivityResult(int request, int result, Intent data) {
     super.onActivityResult(request, result, data);
     if (result != RESULT_OK || data == null || data.getData() == null) { if (request == 51) pendingCsvExportIds = null; return; }
     try {
         if (request == 51) writeCsv(data.getData());
         else if (request == 52) readCsv(data.getData());
         else if (request == 53 && pendingReceipt != null) { ReceiptGenerator.writePng(getContentResolver().openOutputStream(data.getData()), pendingReceipt); pendingReceipt = null; Toast.makeText(this, "Receipt image saved", Toast.LENGTH_SHORT).show(); shareReceipt(data.getData()); }
     } catch (Exception error) { Toast.makeText(this, "Could not process that file", Toast.LENGTH_LONG).show(); }
 }
 private void writeCsv(Uri uri) throws Exception { Set<Long> selection=pendingCsvExportIds; BufferedWriter writer = new BufferedWriter(new OutputStreamWriter(getContentResolver().openOutputStream(uri), "UTF-8")); writer.write("person,contact,category,note,amount,type,due\n"); for (DebtDatabase.Debt debt : db.debts("", "All")) if(selection==null||selection.contains(debt.id)) writer.write(csv(debt.person)+","+csv(debt.contact)+","+csv(debt.category)+","+csv(debt.note)+","+debt.amount+","+csv(debt.type)+","+csv(debt.due)+"\n"); writer.flush(); writer.close(); pref.edit().putLong("last_backup", System.currentTimeMillis()).apply(); db.logEvent("CSV backup exported", selection==null?"A local CSV backup was created":selection.size()+" selected records were exported"); Toast.makeText(this, selection==null?"CSV backup saved":"Selected records exported", Toast.LENGTH_SHORT).show(); pendingCsvExportIds=null; if(selection!=null){selectedRecordIds.clear();render();} }
 private void readCsv(Uri uri) throws Exception { BufferedReader reader = new BufferedReader(new InputStreamReader(getContentResolver().openInputStream(uri), "UTF-8")); String header = reader.readLine(); if (header == null || !header.startsWith("person,")) throw new IOException(); int count = 0; String line; while ((line = reader.readLine()) != null) { String[] row = line.split(",", -1); if (row.length == 7) { try { db.addDebt(row[0], row[1], row[2], row[3], Double.parseDouble(row[4]), row[5], row[6]); count++; } catch (Exception ignored) { } } } reader.close(); Toast.makeText(this, count + " records imported", Toast.LENGTH_SHORT).show(); render(); }
 private String csv(String s) { return s == null ? "" : s.replace(",", " ").replace("\n", " ").replace("\r", " "); }
