 private void exportReceipt(DebtDatabase.Debt debt) { pendingReceipt = debt; Intent intent = new Intent(Intent.ACTION_CREATE_DOCUMENT); intent.setType("image/png"); intent.putExtra(Intent.EXTRA_TITLE, "TrackUtang_Receipt_" + debt.person.replace(" ", "_") + ".png"); startActivityForResult(intent, 53); }
 private void shareReceipt(Uri receipt) { Intent share = new Intent(Intent.ACTION_SEND); share.setType("image/png"); share.putExtra(Intent.EXTRA_STREAM, receipt); share.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION); startActivity(Intent.createChooser(share, "Share payment receipt")); }
 private void homeDueStrip(){int todayCount=0,weekCount=0,laterCount=0;Calendar week=Calendar.getInstance();week.add(Calendar.DAY_OF_YEAR,7);String now=today();String end=new SimpleDateFormat("yyyy-MM-dd",Locale.US).format(week.getTime());for(DebtDatabase.Debt debt:db.debts("","All")){if(debt.remaining()<=0||debt.due==null||!debt.due.matches("\\d{4}-\\d{2}-\\d{2}"))continue;if(debt.due.equals(now))todayCount++;else if(debt.due.compareTo(end)<=0)weekCount++;else laterCount++;}TextView label=text("UPCOMING PAYMENTS",13,teal);label.setTypeface(null,1);label.setPadding(0,dp(18),0,dp(8));content.addView(label);LinearLayout strip=new LinearLayout(this);String[] names={"Today","This week","Later"};int[] counts={todayCount,weekCount,laterCount};for(int i=0;i<3;i++){TextView tile=text(names[i]+"\n"+counts[i],14,ink());tile.setGravity(Gravity.CENTER);tile.setTypeface(null,1);tile.setBackground(shape(dark()?Color.rgb(31,58,78):Color.rgb(234,248,245),18));final int index=i;tile.setOnClickListener(v->CalendarOverviewDialog.show(this,db));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,dp(70),1);if(i==0)p.setMargins(0,0,dp(4),0);else if(i==2)p.setMargins(dp(4),0,0,0);else p.setMargins(dp(2),0,dp(2),0);strip.addView(tile,p);}content.addView(strip);}
